/* Runtime integration: loaded after the game's main script. */
(function(){
 const specs=window.MYTHOLOGY_CH2_ENEMY_SPECS||[],stages=window.MYTHOLOGY_CH2_STAGES||[];
 if(typeof MYTHOLOGY_ENEMY_SPECS!=='undefined')MYTHOLOGY_ENEMY_SPECS.push(...specs);
 specs.forEach(e=>{if(typeof enemyTypes!=='undefined')enemyTypes[e.name]={...e,ability:{...(e.ability||{})},motion:'enemy'};});
 if(typeof enemyTypes!=='undefined'){
  enemyTypes['神話第弐兵']={name:'神話第弐兵',icon:'🪖',trait:'神話',hp:42000,atk:2600,range:95,spd:.8,interval:1.1,attackType:'single',kb:5,money:150,ability:{mythologyV2:[]}};
  enemyTypes['神話第弐分裂体']={name:'神話第弐分裂体',icon:'🧬',trait:'神話',hp:28000,atk:1800,range:80,spd:1.05,interval:.9,attackType:'single',kb:4,money:100,ability:{mythologyV2:[]}};
 }
 if(typeof chapterStages!=='undefined')chapterStages[7]=stages;
 if(typeof chapterClears!=='undefined'&&chapterClears.length<8)chapterClears.push(0);
 const unlockBase=chapterUnlocked;
 chapterUnlocked=function(ch){if(ch===8)return Number(chapterClears[6]||0)>=48;return unlockBase(ch);};
 const scaleBase=chapterScale;
 chapterScale=function(ch,n,key){if(ch===8){const st=stages[Math.max(0,Math.min(47,n-1))],v=Number(st?.schedule?.find(x=>x.enemy===key)?.mult||9);return +(v*(1+Math.max(0,n-1)*.035)).toFixed(2);}return scaleBase(ch,n,key);};
 const renderBase=renderStageSelect;
 renderStageSelect=function(){renderBase();if(selectedChapter===8){const info=document.getElementById('chapterInfo');if(info)info.textContent='🌌 神話編 第2章｜全48ステージ・敵55体・複合属性・32新能力｜第1章全48ステージクリアで解放';}};
 function selectSecond(){selectedMode='japan';selectedChapter=8;selectedStage=1;renderStageSelect();const b=document.getElementById('startBtn');if(b)b.textContent=(stages[0]?.name||'神話編第2章')+(chapterUnlocked(8)?'を開始':'（未解放）');}
 window.mythologyChapter2Select=selectSecond;
 const oldDetail=showEnemyDetail;
 showEnemyDetail=function(key){oldDetail(key);const e=enemyTypes[key]||specs.find(x=>x.name===key);if(!e)return;const list=e.ability?.ch2Abilities||[],body=document.getElementById('detailBody');if(body&&list.length){const extra=list.map(k=>{const d=window.MYTHOLOGY_CH2_ABILITY_INFO.find(x=>x.name===k);return '<div class="enemyAbility"><b>🧬 第2章固有能力：'+k+'</b><br>'+((d&&d.description)||'固有能力')+'</div>';}).join('');body.insertAdjacentHTML('beforeend',extra);}};
})();
